```python
import requests
import json
import time
import random

class HospitalSystem:
    def __init__(self, url, username, password, patient_id):
        self.url = url
        self.username = username
        self.password = password
        self.patient_id = patient_id
        self.patient_data = {}

    def get_patient_data(self):
        try:
            response = requests.get(f"{self.url}/patient/{self.patient_id}", auth=(self.username, self.password))
            if response.status_code == 200:
                return response.json()
            else:
                print(f"Failed to retrieve patient data. Status code: {response.status_code}")
                return None
        except requests.exceptions.RequestException as e:
            print(f"An error occurred: {e}")
            return None

    def update_patient_record(self, new_name, new_address, new_phone_number):
        try:
            response = requests.put(f"{self.url}/patient/{self.patient_id}/update", json={"name": new_name, "address": new_address, "phone_number": new_phone_number}, auth=(self.username, self.password))
            if response.status_code == 200:
                print("Patient record updated successfully")
            else:
                print(f"Failed to update patient record. Status code: {response.status_code}")
        except requests.exceptions.RequestException as e:
            print(f"An error occurred: {e}")

    def get_patient_info(self):
        try:
            response = requests.get(f"{self.url}/patient/{self.patient_id}/info", auth=(self.username, self.password))
            if response.status_code == 200:
                return response.json()
            else:
                print(f"Failed to retrieve patient info. Status code: {response.status_code}")
                return None
        except requests.exceptions.RequestException as e:
            print(f"An error occurred: {e}")
            return None

